function verseOfTheDay(){const verses=[["Whatever you do, work at it with all your heart, as working for the Lord.","COLOSSIANS 3:23"],["The earth is the Lord’s, and everything in it.","PSALM 24:1"],["As for me and my house, we will serve the Lord.","JOSHUA 24:15"],["Trust in the Lord with all your heart and lean not on your own understanding.","PROVERBS 3:5"],["The Lord is my shepherd; I shall not want.","PSALM 23:1"],["Let all that you do be done in love.","1 CORINTHIANS 16:14"],["Commit to the Lord whatever you do, and he will establish your plans.","PROVERBS 16:3"],["This is the day the Lord has made; let us rejoice and be glad in it.","PSALM 118:24"],["Be strong and courageous. Do not be afraid; for the Lord your God will be with you.","JOSHUA 1:9"],["The Lord will guide you always; he will satisfy your needs in a sun-scorched land.","ISAIAH 58:11"],["Those who hope in the Lord will renew their strength.","ISAIAH 40:31"],["Give thanks to the Lord, for he is good; his love endures forever.","PSALM 107:1"],["May the favour of the Lord our God rest on us; establish the work of our hands.","PSALM 90:17"],["A generous person will prosper; whoever refreshes others will be refreshed.","PROVERBS 11:25"]],d=new Date(),start=new Date(d.getFullYear(),0,0),day=Math.floor((d-start)/86400000);return verses[day%verses.length]}
